 53	function isOutsideStoreHours(labelMinute: number | undefined): boolean {
 54	  return (
 55	    labelMinute !== undefined &&
 56	    (labelMinute < STORE_OPENING_MINUTE || labelMinute > STORE_CLOSING_MINUTE)
 57	  );
 58	}
