 39	      const { createSightingOperations } = await import("./sightings.server");
 40	      const operations = createSightingOperations(database);
 41	
 42	      try {
 43	        const first = await operations.create({
 44	          labelDate: "2026-08-11",
 45	          labelMinute: 845,
 46	        });
